// node tests/race.selftest.js — proves the race engine is real and honest:
//  1. its exact P(win) matches brute-force Monte Carlo of the same model;
//  2. on races generated by the fitted model it beats the "best Victory %" favourite and re-learns σ;
//  3. on races with RANDOM winners it shows no edge (≈33%, same as the baselines).
global.window = global;
global.localStorage = { _: {}, getItem(k) { return this._[k] || null; }, setItem(k, v) { this._[k] = v; } };
const R = require('../race.js');
let seed = 7; const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
const gauss = () => Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
const names = Object.keys(R.SPEED), ok = (c, m) => { console.log((c ? 'PASS ' : 'FAIL ') + m); if (!c) process.exitCode = 1; };
const trio = () => { const a = names.slice(); const o = []; while (o.length < 3) o.push(a.splice(Math.floor(rnd() * a.length), 1)[0]); return o; };
const time = (n, roads) => roads.reduce((t, r) => t + 1 / R.SPEED[n][r], 0);

// 1. analytic vs Monte Carlo for one lineup with Desert shown at segment 2
{ const cars = ['Supercar', 'ORV', 'ATV'], k = R.ROADS.indexOf('Desert'), w = [0, 0, 0], N = 60000;
  for (let i = 0; i < N; i++) { const roads = [Math.floor(rnd() * 6), Math.floor(rnd() * 6), k];
    const t = cars.map(n => time(n, roads) * Math.exp(0.3 * gauss())); w[t.indexOf(Math.min(...t))]++; }
  const p = R.predict(cars, 'Desert', 2, { sigma: 0.3 }), mc = w.map(x => x / N);
  ok(p.every((x, i) => Math.abs(x - mc[i]) < 0.012), `exact P(win) ${p.map(x => x.toFixed(3))} ≈ Monte Carlo ${mc.map(x => x.toFixed(3))}`); }

// 2 + 3. full loop through forecast/settle, like the overlay does it
function run(random) {
  global.localStorage._ = {}; const s = R.load();
  for (let i = 0; i < 600; i++) {
    const cars = trio(), roads = [0, 1, 2].map(() => Math.floor(rnd() * 6)), idx = Math.floor(rnd() * 3);
    const t = cars.map(n => time(n, roads) * Math.exp(0.3 * gauss()));
    const winner = random ? cars[Math.floor(rnd() * 3)] : cars[t.indexOf(Math.min(...t))];
    const odds = cars.map(n => (2 + rnd() * 2).toFixed(1) + '/' + (97 / R.VICTORY[n]).toFixed(1));
    R.settle(s, R.forecast(s, { cars, road: R.ROADS[roads[idx]], roadIdx: idx, odds, t: 1 }), winner);
  }
  return { st: R.stats(s), sigma: s.params.sigma };
}
{ const { st, sigma } = run(false), e = st.eng / st.n, f = st.fav / st.n;
  console.log(`  model data: engine ${(100 * e).toFixed(1)}%  fav ${(100 * f).toFixed(1)}%  crowd ${(100 * st.crowd / st.n).toFixed(1)}%  (n=${st.n}, CI ${st.ci.map(x => (100 * x).toFixed(0)).join('–')}%)  σ fitted ${sigma}`);
  ok(e > f + 0.02, 'engine beats the Victory% favourite when the model is true');
  ok(Math.abs(sigma - 0.3) <= 0.1, 'σ re-learned from results ≈ 0.3'); }
{ const { st } = run(true), e = st.eng / st.n;
  console.log(`  random winners: engine ${(100 * e).toFixed(1)}%  fav ${(100 * st.fav / st.n).toFixed(1)}%  (n=${st.n})`);
  ok(Math.abs(e - 1 / 3) < 0.06, 'no fake edge when winners are random (≈33%)'); }
